const $=s=>document.querySelector(s);let data=[],category='',language='',query='';const icons=['⌘','◇','◉','⇄','⬡','⌁','>_','▤','▣','⊞','{ }','♧','⑂','▥','⌗','◎','▰'];const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function matches(t){return (!language||t.languages.includes(language))&&(!query||[t.title,t.language,t.category].join(' ').toLowerCase().includes(query.toLowerCase()))}
function render(){const groups=data.map(c=>({...c,tutorials:c.tutorials.filter(t=>matches({...t,category:c.name}))})).filter(c=>c.tutorials.length);$('#clear').hidden=!category&&!language&&!query;document.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===language));$('#all').classList.toggle('active',!category);document.querySelectorAll('[data-cat]').forEach(b=>b.classList.toggle('active',b.dataset.cat===category));$('#heading').textContent=category?'Build your own '+category:query||language?'Your next project awaits.':'Explore the collection.';$('#breadcrumb').textContent=category?'THE COLLECTION / '+category.toUpperCase():'FIND YOUR NEXT DEEP DIVE';const showTutorials=!!(category||query||language);const tutorials=groups.filter(c=>!category||category===c.name).flatMap(c=>c.tutorials.map(t=>({...t,category:c.name})));$('#resultCount').textContent=showTutorials?`${tutorials.length} tutorials`:`${groups.length} categories to explore`;$('#empty').hidden=showTutorials?tutorials.length>0:groups.length>0;$('#grid').innerHTML=showTutorials?tutorials.map(t=>`<a class="card tutorial" href="${esc(t.url)}" target="_blank" rel="noopener noreferrer"><small>${esc(t.category)}${t.video?' · VIDEO':''}</small><h3>${esc(t.title)}</h3><div class="card-bottom">${t.languages.map(l=>`<span class="tag">${esc(l)}</span>`).join('')}<span class="arrow">↗</span></div></a>`).join(''):groups.map(c=>`<button class="card" data-open="${esc(c.name)}"><div class="card-top"><span class="icon">${esc(icons[data.indexOf(data.find(d=>d.name===c.name))%icons.length])}</span><span class="arrow">↗</span></div><small>BUILD YOUR OWN</small><h3>${esc(c.name)}</h3><div class="card-bottom">${[...new Set(c.tutorials.flatMap(t=>t.languages))].slice(0,2).map(l=>`<span class="tag">${esc(l)}</span>`).join('')}<span class="count">${c.tutorials.length} guides</span></div></button>`).join('');document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>choose(b.dataset.open))}
function choose(c){category=c;render();$('#heading').scrollIntoView({behavior:'smooth',block:'center'})}
function init(md){data=parseReadme(md);if(!data.length)throw Error('Empty collection');const languages=[...new Set(data.flatMap(c=>c.tutorials.flatMap(t=>t.languages)))].sort();$('#tutorialCount').textContent=data.reduce((n,c)=>n+c.tutorials.length,0);$('#categoryCount').textContent=data.length;$('#catCount').textContent=data.length;$('#languageCount').textContent=languages.length;$('#nav').innerHTML=data.map(c=>`<button class="nav" data-cat="${esc(c.name)}"><span>${esc(c.name)}</span><small>${c.tutorials.length}</small></button>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>choose(b.dataset.cat));$('#language').innerHTML='<option value="">All languages</option>'+languages.map(l=>`<option>${esc(l)}</option>`).join('');render()}
$('#search').oninput=e=>{query=e.target.value;render()};$('#language').onchange=e=>{language=e.target.value;render()};document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{language=language===b.dataset.lang?'':b.dataset.lang;$('#language').value=language;render()});$('#all').onclick=()=>{category='';render()};$('#clear').onclick=()=>{category=language=query='';$('#language').value=$('#search').value='';render()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});
(async()=>{try{const r=await fetch('README.md');if(!r.ok)throw Error();init(await r.text());$('#status').textContent='Included snapshot · Checking GitHub for the latest collection…'}catch{ $('#status').textContent='Loading from GitHub…'}try{const r=await fetch('https://raw.githubusercontent.com/codecrafters-io/build-your-own-x/master/README.md',{signal:AbortSignal.timeout(12000),cache:'no-cache'});if(!r.ok)throw Error();init(await r.text());$('#language').value=language;$('#status').textContent='● Synced with GitHub · Updated just now'}catch{$('#status').textContent=data.length?'Using the included collection · Live refresh unavailable. Reload to retry.':'Unable to load tutorials. Please reload to retry.'}})();
